<script setup lang="ts">
type ReportFilters={periodStart:string;periodEnd:string;marketplace:string;product:string;channel:string}
const props=defineProps<{filters:ReportFilters}>();const{products,orders}=useAppData();const parseDate=(value:unknown)=>{const text=String(value||'');if(/^\d{2}\/\d{2}\/\d{4}$/.test(text)){const [day,month,year]=text.split('/').map(Number);return new Date(year,month-1,day)}const date=new Date(text);return Number.isNaN(date.getTime())?null:date};const isCancelled=(value:unknown)=>String(value||'').trim().toLowerCase()==='cancelado';const productRows=computed(()=>{const start=new Date(`${props.filters.periodStart}T00:00:00`),end=new Date(`${props.filters.periodEnd}T23:59:59`),totals=new Map<string,{qty:number;revenue:number;profit:number}>();for(const order of orders.value){const date=parseDate(order.date);if(!date||date<start||date>end||isCancelled(order.status)||(props.filters.marketplace!=='Todos'&&(order.marketplace||'Sem marketplace')!==props.filters.marketplace)||(props.filters.product!=='Todos'&&order.product!==props.filters.product)||(props.filters.channel!=='Todos'&&(props.filters.channel==='Diretas'?order.salesChannel!=='direct':order.salesChannel!=='marketplace')))continue;const row=totals.get(order.product)||{qty:0,revenue:0,profit:0};row.qty+=Number(order.qty||0);row.revenue+=Number(order.gross||0);row.profit+=Number(order.profit||0);totals.set(order.product,row)}return products.value.filter(product=>props.filters.product==='Todos'||product.name===props.filters.product).map(product=>({...product,...(totals.get(product.name)||{qty:0,revenue:0,profit:0})})).sort((a,b)=>b.revenue-a.revenue)})</script>
<template><div class="dashboard-grid"><PanelCard title="Produtos mais relevantes" subtitle="Vendas, lucro e margem no período filtrado"><div class="table-scroll"><table class="data-table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Faturamento</th><th>Lucro</th><th>Margem cadastrada</th></tr></thead><tbody><tr v-if="!productRows.length"><td colspan="5">Nenhum produto encontrado.</td></tr><tr v-for="item in productRows.slice(0,10)" :key="item.id || item.sku"><td><div class="table-product"><ProductThumb :type="item.thumb" :size="25"/>{{item.name}}</div></td><td>{{item.qty}}</td><td>{{formatCurrency(item.revenue)}}</td><td :class="item.profit>=0?'money-positive':'money-negative'">{{formatCurrency(item.profit)}}</td><td>{{Number(item.margin||0).toFixed(1)}}%</td></tr></tbody></table></div></PanelCard></div></template>
